chunks = {
    "c1": "Steps to reset a forgotten password.",
    "c2": "How to update your login credentials.",
    "c3": "Shipping timelines for international orders.",
}

def fake_search(query, chunks):
    words = set(query.lower().split())
    scores = {}
    for chunk_id, text in chunks.items():
        overlap = len(words & set(text.lower().split()))
        if overlap > 0:
            scores[chunk_id] = overlap
    return sorted(scores.items(), key=lambda x: -x[1])

query_variations = [
    "how do I reset my password",
    "steps to change login credentials",
    "forgot my password what do I do",
]

print("Generated query variations (generating query variations):")
for q in query_variations:
    print(f" {q!r}")

all_results = []
for q in query_variations:
    results = fake_search(q, chunks)
    print(f"\n Results for {q!r}: {results}")
    all_results.append([r[0] for r in results])

def reciprocal_rank_fusion(result_lists, k=60):
    scores = {}
    for results in result_lists:
        for rank, chunk_id in enumerate(results, start=1):
            scores[chunk_id] = scores.get(chunk_id, 0) + 1 / (k + rank)
    return sorted(scores.items(), key=lambda x: -x[1])

merged = reciprocal_rank_fusion(all_results)
print(f"\nMerged results across all variations (merging results across variations): {merged}")
